ArrivalTimelineItem.supportsAudit = (_purchase: Purchase, item: PurchaseItem, audit: Audit) =&gt; {
    const [from, to] = getDates(item, audit);
    return from &amp;&amp; to;
};

const getDates = (item: PurchaseItem, audit: Audit) =&gt; {
    if (audit.data?.items) {
        const matchingAuditItem: any =
            isArray(audit.data?.items) &amp;&amp;
            audit.data.items.find((auditItem: any) =&gt; {
                return auditItem.id === item?.id &amp;&amp; auditItem.arrivalDateTime;
            });

        if (matchingAuditItem?.arrivalDateTime &amp;&amp; !matchingAuditItem?.product) {
            // Old - new to get a positive amount because we are returning money
            return [matchingAuditItem.arrivalDateTime.old, matchingAuditItem.arrivalDateTime.new];
        }
    }

    return [null, null];
};

